contract InvMutTest {
    C c;
    bool phase;
    uint d2;
    constructor(C _c) { c = _c; phase = false; d2 = 0; }
    function run(uint amount, uint redeposit) public payable {
        require(amount > 0);
        require(address(this).balance >= redeposit);
        uint startC = address(c).balance;
        c.deposit{value: amount}();
        phase = true;
        d2 = redeposit;
        c.withdrawAll();
        phase = false;
        assert(address(c).balance + amount == startC + d2);
    }
    receive() external payable {
        if (phase && d2 > 0) {
            uint v = d2;
            d2 = 0;
            c.deposit{value: v}();
        }
    }
}
